"""Zoo 1.118.1: the crowd barrier's feet stand proud of a building's floor skin (the factory's roadmap 267).

The factory's cold run 9359 framed arena_a02's crowd barriers with no feet, their legs planted in the carpet: Deli
Counter lays a room's floor finish as a 2 cm skin over the slab and stands props on the slab under it, so 1.118.0's
9.5 mm flat-bar feet were buried whole.

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * zoo_keeper/core/crowd_barrier_forms.py -- the feet are 2 x 1-1/2 in rectangular tube, 1.8 cm proud of a 2 cm skin.
  * zoo_keeper/genome/species/crowd_barrier.json -- its notes say so.
  * tests/test_crowd_barrier.py -- the feet clear the skin at every size; fails on 1.118.0.
  * VERSION 1.118.0 -> 1.118.1, CHANGELOG.

Generated by `patches/zoo_crowd_feet/gen_zoo_crowd_feet.py` from a proven clone; its census, dry runs and prove run
are beside it.

    python patches/patch_zoo_crowd_feet.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/core/crowd_barrier_forms.py': 'd388c7592737973e', 'tests/test_crowd_barrier.py': '6c5e9c24f5477028', 'zoo_keeper/genome/species/crowd_barrier.json': 'a73bedc8c66039be'}
EDITS = {'zoo_keeper/core/crowd_barrier_forms.py': [('lines 6-6', 'a welded tube frame on two flat feet, vertical pickets between its rails, hooks at one end that drop over the next\n', 'a welded tube frame on two tube feet, vertical pickets between its rails, hooks at one end that drop over the next\n'), ('lines 16-17', "  * `FOOT_W`, `FOOT_T`: 2 in flat bar, drawn 3/8 in thick where the steel is 1/4, so it holds a pixel a few metres out\n    (as the stoop railing's pickets and the fence's tension wire are drawn heavier than they are);\n", "  * `FOOT_W`, `FOOT_T`: feet of 2 x 1-1/2 in rectangular steel tube, as many barricades' are. NOT the 1/4 in flat bar\n    of the lowest feet, which 1.118.0 drew 3/8 in thick: Deli Counter lays a room's floor finish as a 2 cm skin over\n    the slab and stands every prop on the slab under it (its `floors.SKIN_THICK`), so a foot thinner than 2 cm is\n    buried whole -- the factory's cold run 9359 framed arena_a02's barricades with their legs planted straight into\n    the carpet. 1-1/2 in stands 1.8 cm proud of that skin, and on bare ground it is a foot a fabricator would weld;\n"), ('lines 36-37', "COLLISION: the panel -- the frame's thickness, leg to leg, floor to top. The feet stay out of it: a 3/8 in plate is\nunder any step. Deli Counter writes its volume's own collider in the greybox the graders walk (arena_a02's is the\n", "COLLISION: the panel -- the frame's thickness, leg to leg, floor to top. The feet stay out of it: 1-1/2 in is under\nany step. Deli Counter writes its volume's own collider in the greybox the graders walk (arena_a02's is the\n"), ('lines 52-53', 'FOOT_W = round(2 * IN, 4)             # flat bar across X\nFOOT_T = round(0.375 * IN, 4)         # its thickness, drawn heavier than the 1/4 in steel\n', "FOOT_W = round(2 * IN, 4)             # the foot's tube across X\nFOOT_T = round(1.5 * IN, 4)           # its height: proud of a 2 cm floor skin (the docstring)\n"), ('lines 116-116', "    # the two flat feet, the panel's depth long, under the legs\n", "    # the two feet, rectangular tube the panel's depth long, under the legs\n")], 'tests/test_crowd_barrier.py': [('lines 157-158', '\ndef test_an_open_end_is_narrower_than_what_hides_it():\n', '\ndef test_the_feet_stand_proud_of_a_floor_skin():\n    """1.118.1: Deli Counter lays a room\'s floor finish as a 2 cm skin over the slab and stands a prop on the slab under\n    it (its `floors.SKIN_THICK`), so a foot under 2 cm is buried -- the factory\'s cold run 9359 framed 1.118.0\'s 9.5 mm\n    feet out of sight, the legs planted in the carpet. A foot\'s top clears that skin by a centimetre or more, at every\n    size. FAILS ON 1.118.0."""\n    skin = 0.02\n    assert F.FOOT_T - skin >= 0.01\n    for w, d, h in SIZES:\n        feet = [p for p in F.plan(w, d, h)["prims"] if len(p["faces"]) == 6]\n        assert len(feet) == 2\n        assert all(max(v[2] for v in p["verts"]) - (-h / 2) >= skin + 0.01 for p in feet)\n\n\ndef test_an_open_end_is_narrower_than_what_hides_it():\n')], 'zoo_keeper/genome/species/crowd_barrier.json': [('lines 6-6', '    "notes": "Factory roadmap 267, the walker\'s look review of 2026-10-20 on arena_a02\'s four barrier volumes (3.0 x 0.8 x 1.2 m, built as boxes): \'Crowd rails (a new model)\', not the jersey barrier. REFERENCE: a hot-dip galvanised steel crowd-control barricade -- one interlocking panel of 1-1/2 in tube legs and 1-1/4 in rails with 3/4 in pickets, fourteen to a 7.5 ft panel, the bottom rail 8 in up, on two flat-bar feet, hooks at one end that drop over the next panel\'s leg. The defaults are the common fabricated sizes, 7.5 ft x 43 in on 24 in feet; the ranges hold arena_a02\'s slot (`core/crowd_barrier_forms.py`). One material. Collision: the panel; Deli Counter writes its volume\'s own collider in the greybox. BUILT: 412 tris at the default dims, 476 at arena_a02\'s, 508 at the largest corner (2026-10-20)."\n', '    "notes": "Factory roadmap 267, the walker\'s look review of 2026-10-20 on arena_a02\'s four barrier volumes (3.0 x 0.8 x 1.2 m, built as boxes): \'Crowd rails (a new model)\', not the jersey barrier. REFERENCE: a hot-dip galvanised steel crowd-control barricade -- one interlocking panel of 1-1/2 in tube legs and 1-1/4 in rails with 3/4 in pickets, fourteen to a 7.5 ft panel, the bottom rail 8 in up, on two feet of 2 x 1-1/2 in rectangular tube (1.118.1: flat bar is buried under a building\'s 2 cm floor skin), hooks at one end that drop over the next panel\'s leg. The defaults are the common fabricated sizes, 7.5 ft x 43 in on 24 in feet; the ranges hold arena_a02\'s slot (`core/crowd_barrier_forms.py`). One material. Collision: the panel; Deli Counter writes its volume\'s own collider in the greybox. BUILT: 412 tris at the default dims, 476 at arena_a02\'s, 508 at the largest corner (2026-10-20)."\n')]}
NEW_FILES = {}
CHANGELOG = "## [1.118.1] - the crowd barrier's feet stand proud of a building's floor skin\n\n**Found in the factory's cold run 9359**, which framed arena_a02's four crowd barriers (roadmap 267; the factory's\n`docs/findings/crowd_barrier_267/`): the barricades stood with no feet, their legs planted straight into the carpet.\nDeli Counter lays a room's floor finish as a 2 cm skin over the slab and stands every prop on the slab under it (its\n`floors.SKIN_THICK`), so 1.118.0's 9.5 mm flat-bar feet were buried whole.\n\n### Changed\n- `core/crowd_barrier_forms.py`: the feet are 2 x 1-1/2 in rectangular steel tube, as many barricades' are, standing\n  1.8 cm proud of a 2 cm skin; the legs' open ends still lie inside them. Triangles (348 / 412 / 508 at the genome's\n  corners, 476 at arena_a02's), parts, material and extents are 1.118.0's; the coplanar census re-run the same way\n  reads 0 pairs at all three corners and the bollard control its known 2 / 2 / 1 (the factory's\n  `patches/zoo_crowd_feet/census.log`).\n\n### Records corrected\n- 1.118.0's kit build named its module `prop_crowd_barrier_delco_1997_04_w300_d80_h120`: its slots kept Deli Counter\n  0.241.0's style. Deli Counter 0.242.0 declares `metal_bare` tenth in arena_a02's palette, its slots carry style 10,\n  and the module ships as `prop_crowd_barrier_delco_1997_10_w300_d80_h120` -- the same geometry and material (the\n  factory's `patches/dc_crowd_barrier/kit_real_slots.log`).\n\n### Tests\n- `tests/test_crowd_barrier.py`: `test_the_feet_stand_proud_of_a_floor_skin`, a foot's top a centimetre or more over a\n  2 cm skin at every size. It fails on 1.118.0, and nothing else does.\n\n"
OLD_VERSION, NEW_VERSION = '1.118.0', '1.118.1'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
